// Test-only entry. The owned harness must establish a fresh isolated profile.
import React from'react';import{createRoot}from'react-dom/client';import App from'../../src/App.jsx';import'../../src/index.css';import'../../src/studio.css';import{createProjectStore}from'../../src/persistence/projectStore.js';import{PROJECT_DATABASE}from'../../src/persistence/projectSchema.js';import{exportPortableWorkspace,stagePortableWorkspace}from'../../src/persistence/workspacePortability.js';import{restoreWorkspace}from'../../src/persistence/workspaceRestore.js';import{createMemoryCoordinator}from'../../src/persistence/assistantMemoryCoordinator.js';
const token=new URLSearchParams(location.search).get('token');if(!/^[0-9a-f-]{36}$/.test(token??'')||!(await(await fetch('/__scope8a_guard?token='+token)).json()).isolated)throw Error('Owned isolated harness required');const existing=localStorage.getItem('scope8a-owned-profile');if(existing&&existing!==token)throw Error('Foreign profile');if(!existing&&(await indexedDB.databases()).some(d=>d.name===PROJECT_DATABASE))throw Error('Refuse existing CANDY data');localStorage.setItem('scope8a-owned-profile',token);
const store=createProjectStore(),pause=ms=>new Promise(r=>setTimeout(r,ms??30)),check=(v,m)=>{if(!v)throw Error(m);},errors=[],network=[];let root,hook=null;
addEventListener('error',e=>errors.push(e.message));addEventListener('unhandledrejection',e=>errors.push(String(e.reason)));
const originalFetch=fetch.bind(window);window.fetch=async(url,options)=>{let request;try{if(options?.body&&String(url).includes('/api/chat'))request=JSON.parse(options.body);}catch{}try{const r=await originalFetch(url,options);if(/api\/(tags|chat)/.test(String(url)))network.push({url:String(url),status:r.status,request});return r;}catch(e){network.push({url:String(url),error:String(e)});throw e;}};
async function wait(fn,label,ms=40000){const until=Date.now()+ms;while(Date.now()<until){const v=await fn();if(v)return v;await pause();}throw Error('Timeout '+label+' '+document.body.textContent.slice(-2200));}
const panel=()=>document.querySelector('[data-resume-state]'),ws=()=>document.querySelector('[data-workspace-storage]'),mem=()=>document.querySelector('[data-testid=assistant-memory]'),model=()=>document.querySelector('[data-model-continuity]'),port=()=>document.querySelector('[data-portability-state]'),button=(s,scope=document)=>[...scope.querySelectorAll('button')].find(x=>x.textContent===s);
function edit(el,value){check(el,'editable control');Object.getOwnPropertyDescriptor(el.tagName==='SELECT'?HTMLSelectElement.prototype:el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event(el.tagName==='SELECT'?'change':'input',{bubbles:true}));}
function hold(stage){console.log('S8A_BOUNDARY:'+stage);const until=Date.now()+45000;while(Date.now()<until){}throw Error('Bounded test hook was not interrupted');}
const put=IDBObjectStore.prototype.put,transaction=IDBDatabase.prototype.transaction,complete=Object.getOwnPropertyDescriptor(IDBTransaction.prototype,'oncomplete');
IDBObjectStore.prototype.put=function(value,...args){if(hook==='before-root'&&this.name==='workspaceRoots'){hook=null;hold('before-root-publication');}return put.call(this,value,...args);};
IDBDatabase.prototype.transaction=function(names,mode,...args){if(hook==='write-failure'&&mode==='readwrite')throw new DOMException('Scope 8A injected write failure','QuotaExceededError');const tx=transaction.call(this,names,mode,...args);if(hook==='after-commit'&&mode==='readwrite'&&[...tx.objectStoreNames].includes('workspaceRoots')&&[...tx.objectStoreNames].includes('assistantMemories')){hook=null;Object.defineProperty(tx,'oncomplete',{configurable:true,get(){return complete.get.call(tx);},set(fn){complete.set.call(tx,function(e){hold('after-native-commit-before-receipt');fn?.call(tx,e);});}});}return tx;};
async function mount(){root=createRoot(document.getElementById('root'));root.render(React.createElement(React.StrictMode,null,React.createElement(App)));await wait(()=>panel()&&panel().dataset.resumeState!=='RESTORING','startup');return{state:panel().dataset.resumeState,workspace:!!ws()};}
async function ready(){await wait(()=>ws()&&ws().dataset.workspaceStorage!=='loading'&&panel().dataset.resumeState!=='RESTORING','usable App');await pause(150);}
async function resume(){button('Resume workspace',panel()).click();await ready();}
async function assistant(){document.getElementById('tools-tab-assistant').click();await wait(()=>mem()&&!mem().textContent.includes('Loading project memory'),'memory');mem().open=true;document.getElementById('agent-workspace-tab-settings').click();await wait(model,'model controls');}
async function upload(text,name='alpha.txt'){const t=new DataTransfer();t.items.add(new File([text],name,{type:'text/plain'}));const input=document.querySelector('.hg-input-card input[type=file]')??document.querySelector('input[type=file]');input.files=t.files;input.dispatchEvent(new Event('change',{bubbles:true}));await wait(()=>ws().dataset.workspaceStorage==='committed'&&document.querySelector('.hg-input-card textarea')?.value.includes(text),'source commit');}
async function convert(){[...document.querySelectorAll('.hg-input-card button')].find(b=>/convert/i.test(b.textContent)).click();await wait(()=>ws().dataset.workspaceStorage==='committed'&&panel().querySelectorAll('dd')[1]?.textContent.includes('Available'),'graph commit');await pause(180);}
async function currentId(){return(await store.readResumePreferences()).selectedProjectId??(await store.defaultProject()).projectId;}
async function remember(content,topic='policy'){await assistant();edit(mem().querySelector('[aria-label="Memory topic"]'),topic);edit(mem().querySelector('textarea'),content);await pause();button('Remember',mem()).click();await wait(async()=>mem().textContent.includes('Memory committed')&&(await store.readMemory(await currentId())).envelope.records.some(r=>r.content===content),'memory commit');}
async function summary(id){const p=await store.readProject(id),x=await restoreWorkspace(store,id),m=await store.readMemory(id),thread=await store.load(id);return{projectId:id,revision:p.revision,rootSha256:x.root?.sha256??null,publicationRevision:x.root?.publicationRevision??null,graphFingerprint:x.graph?.graphFingerprint??null,sources:x.sources.map(s=>({objectId:s.objectId,sha256:s.sha256,provenance:s.provenance,base64:btoa(String.fromCharCode(...new Uint8Array(s.bytes)))})),memorySha256:m.envelope?.sha256??null,memories:m.envelope?.records??[],pendingAction:thread.record?.pendingAction,messages:thread.record?.messages,profile:(await store.readConnectionProfile()).profile};}
async function selectFile(b64,name='misleading.bin'){button('Import workspace',port()).click();const input=await wait(()=>document.querySelector('[aria-label="Portable workspace file"]'),'file picker'),raw=Uint8Array.from(atob(b64),c=>c.charCodeAt(0)),t=new DataTransfer();t.items.add(new File([raw],name,{type:'application/octet-stream'}));input.files=t.files;input.dispatchEvent(new Event('change',{bubbles:true}));await wait(()=>['ready','rejected'].includes(port().dataset.portabilityState),'file validation');return{state:port().dataset.portabilityState,message:port().textContent};}
async function exportFile(){const file=await exportPortableWorkspace(store,await currentId());return{...file,bytes:undefined,base64:btoa(String.fromCharCode(...file.bytes))};}
window.s8a={ready:true,errors,network,mount,resume,readyApp:ready,assistant,upload,convert,remember,summary,currentId,selectFile,exportFile,arm:kind=>{hook=kind;},
 async seed(){await mount();await ready();await upload('h0: A, B\nh1: B, C');await convert();await remember('Project Alpha forbids implicit projection.');return summary(await currentId());},
 async connect(auto=false){await assistant();edit(model().querySelector('[aria-label="Selected local model"]'),'qwen3:8b');await pause();button('Connect selected model',model()).click();await wait(()=>model().dataset.modelContinuity==='connected','real qwen discovery');const toggle=model().querySelector('[aria-label="Auto reconnect"]');if(toggle.checked!==auto)toggle.click();await wait(async()=>(await store.readConnectionProfile()).profile.autoReconnectEnabled===auto,'model preference commit');return{state:model().dataset.modelContinuity,network};},
 async send(){await assistant();const from=network.length;edit(document.getElementById('hypergraph-agent-composer'),'Tell me about this project and its remembered constraints.');await pause();document.querySelector('.agent-composer button[type=submit]').click();await wait(()=>network.slice(from).some(x=>x.status===200&&x.request?.model==='qwen3:8b'),'real qwen inference',150000);await wait(()=>/Last request: conversation · success/.test(document.body.textContent),'model success',150000);return network.slice(from);},
 async unsent(){await assistant();edit(document.getElementById('hypergraph-agent-composer'),'Delete hyperedge h0');},
 async exportUi(){button('Export workspace',port()).click();await wait(()=>port().dataset.portabilityState==='exported','UI export download');},
 async importNew(){button('Import as separate workspace',port()).click();await wait(()=>panel().textContent.includes('Import complete')||port().dataset.portabilityState==='conflict'||port().dataset.portabilityState==='rejected','import publication');return{state:panel().dataset.resumeState,portability:port().dataset.portabilityState,text:panel().textContent,projects:(await store.listProjects()).map(x=>x.manifest?.projectId)};},
 async replace(confirm=true){button('Replace selected workspace…',port()).click();await wait(()=>document.querySelector('dialog[open]'),'replacement confirmation');check(document.querySelector('dialog h2').textContent==='Replace selected workspace?','correct confirmation');check(document.activeElement.textContent==='Cancel','safe initial focus');button(confirm?'Confirm':'Cancel',document.querySelector('dialog')).click();if(confirm)await wait(()=>panel().textContent.includes('Import complete')||port().dataset.portabilityState==='conflict'||port().dataset.portabilityState==='rejected','replacement publication');else await wait(()=>port().dataset.portabilityState==='ready','cancelled replacement');return{state:panel().dataset.resumeState,text:panel().textContent};},
 async fresh(){button('Start fresh session',panel()).click();await ready();return currentId();},
 async choose(id){edit(panel().querySelector('[aria-label="Saved workspace"]'),id);await wait(()=>panel().dataset.resumeState==='RESTORE_AVAILABLE','project chooser');await resume();return currentId();},
 async reload(){button('Reload saved data',panel()).click();await pause(100);await wait(()=>panel().dataset.resumeState!=='RESTORING','explicit owner reload');if(!ws())await resume();await ready();return currentId();},
 async state(){return{resume:panel()?.dataset.resumeState,portability:port()?.dataset.portabilityState,durability:document.querySelector('[data-durability]')?.textContent,model:model()?.dataset.modelContinuity,source:document.querySelector('.hg-input-card textarea')?.value,unsent:document.getElementById('hypergraph-agent-composer')?.value,projects:(await store.listProjects()).map(x=>x.manifest?.projectId),network,errors};},
 async editSource(text){edit(document.querySelector('.hg-input-card textarea'),text);await wait(()=>['read_only','error'].includes(ws().dataset.workspaceStorage),'stale save rejection');return{state:ws().dataset.workspaceStorage,durability:document.querySelector('[data-durability]').textContent};},
 async cancelUnsavedImport(){button('Import as separate workspace',port()).click();await wait(()=>document.querySelector('dialog[open]'),'unsaved import review');check(document.querySelector('dialog h2').textContent==='Leave unsaved changes?','qualified unsaved-edit review');check(document.activeElement.textContent==='Cancel','safe initial focus');button('Cancel',document.querySelector('dialog')).click();await wait(()=>port().dataset.portabilityState==='ready','cancel unsaved import');return{source:document.querySelector('.hg-input-card textarea').value,projects:(await store.listProjects()).map(x=>x.manifest?.projectId),state:panel().dataset.resumeState};},
 async openDelete(){panel().querySelector('details').open=true;button('Delete saved workspace…',panel()).click();await wait(()=>document.querySelector('dialog[open]'),'delete review');},
 async confirmDelete(){button('Confirm',document.querySelector('dialog')).click();await wait(()=>[...document.querySelectorAll('[role=alert]')].some(x=>x.textContent.includes('Nothing was cleared')),'stale delete rejection');return true;},
 async rawImport(b64){return store.importWorkspace(await stagePortableWorkspace(Uint8Array.from(atob(b64),c=>c.charCodeAt(0))));},
};console.log('S8A_PAGE_READY');
